from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + skill[i]

        start = 0
        for j in range(m - 1):
            mj = mana[j]
            mj1 = mana[j + 1]
            best = 0
            for i in range(n):
                v = P[i + 1] * mj - P[i] * mj1
                if v > best:
                    best = v
            start += best

        return start + P[n] * mana[-1]
